// Path hashing compared with GzsTool.Core and CityHash.dll output
using System.Globalization;
using DMM.Core.Hashing;

namespace DMM.Tests;

public static class HashingTests
{
    // Columns: name, HashFileName, HashFileName(no ext removal), HashFileNameWithExtension, HashFileNameLegacy,
    // HashFileNameLegacy(no ext removal), SnakeBite NameToHash. Generated by GzsTool.Core under mono.
    [Test]
    public static void MatchesGzsTool()
    {
        string file = Path.Combine(TestRunner.FixturesDir, "hashes", "gzstool_hashes.tsv");
        string? full = Environment.GetEnvironmentVariable("DMM_HASHES_FULL");
        if (full != null && File.Exists(full))
            file = full;

        int rows = 0;
        foreach (string line in File.ReadLines(file, AnsiText.Encoding))
        {
            string[] c = line.Split('\t');
            string name = c[0];
            Check(c[1], () => FoxPath.HashFileName(name), name, "HashFileName");
            Check(c[2], () => FoxPath.HashFileName(name, false), name, "HashFileName(false)");
            Check(c[3], () => FoxPath.HashFileNameWithExtension(name), name, "HashFileNameWithExtension");
            Check(c[4], () => FoxPath.HashFileNameLegacy(name), name, "HashFileNameLegacy");
            Check(c[5], () => FoxPath.HashFileNameLegacy(name, false), name, "HashFileNameLegacy(false)");
            Check(c[6], () => FoxPath.NameToHash(name), name, "NameToHash");
            rows++;
        }
        Assert.True(rows > 1000, $"only {rows} rows in {file}");
    }

    private static void Check(string expected, Func<ulong> actual, string name, string what)
    {
        if (expected.StartsWith("ERR:", StringComparison.Ordinal))
        {
            try { actual(); }
            catch (Exception) { return; }
            throw new Exception($"{what}({name}): GzsTool threw {expected}, DMM returned a value");
        }
        ulong value = actual();
        Assert.Equal(ulong.Parse(expected, NumberStyles.HexNumber), value, $"{what}({name})");
    }

    [Test]
    public static void UpdateNameFindsDictionaryPath()
    {
        QarDictionary dictionary = QarDictionary.Load(Path.Combine(TestRunner.DataDir, "qar_dictionary.txt"));
        const string path = "/Assets/tpp/pack/mission2/init/init";
        ulong hash = FoxPath.HashFileName(path) & FoxPath.PathHashMask;
        Assert.Equal(path + ".fpkd", dictionary.UpdateName("/" + hash.ToString("x") + ".fpkd"), "UpdateName");
        Assert.Equal(path + ".eng.lng", dictionary.UpdateName("/" + hash.ToString("x") + ".eng.lng"), "UpdateName inner extension");
        Assert.Equal<string?>(null, dictionary.UpdateName("/Assets/tpp/pack/mission2/init/init.fpkd"), "UpdateName on a real path");
    }

    [Test]
    public static void BuiltInDictionariesMatchTheDataFiles()
    {
        using var empty = new TempDir();
        string qarFile = File.ReadAllText(Path.Combine(TestRunner.DataDir, "qar_dictionary.txt"));
        string fpkFile = File.ReadAllText(Path.Combine(TestRunner.DataDir, "fpk_dictionary.txt"));
        using (TextReader reader = DictionaryFile.Open(empty.Path, "qar_dictionary.txt"))
            Assert.True(reader.ReadToEnd() == qarFile, "built-in qar_dictionary.txt");
        using (TextReader reader = DictionaryFile.Open(empty.Path, "fpk_dictionary.txt"))
            Assert.True(reader.ReadToEnd() == fpkFile, "built-in fpk_dictionary.txt");

        File.WriteAllText(Path.Combine(empty.Path, "qar_dictionary.txt"), "/Assets/override.lua\n");
        using (TextReader reader = DictionaryFile.Open(empty.Path, "qar_dictionary.txt"))
            Assert.True(reader.ReadToEnd() == "/Assets/override.lua\n", "file next to the program wins");
    }
}
